def select_words(s, n):
    """
    Given a string s and a natural number n, this function returns a list of all words
    from string s that contain exactly n consonants, in order these words appear in the string s.
    If the string s is empty, it returns an empty list.
    Note: The input string contains only letters and spaces.
    """
    if not s:
        return []
    
    # Define a helper function to count consonants in a word
    def count_consonants(word):
        consonants = "bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ"
        return sum(1 for char in word if char in consonants)

    # Split the string into words
    words = s.split()
    result = []

    for word in words:
        if count_consonants(word) == n:
            result.append(word)

    return result

