def monotonic(l: list) -> bool:
    """Return True if list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    # Check if the list is empty or has one element, which is trivially monotonic
    if not l or len(l) == 1:
        return True

    # Determine the initial direction of the sequence (increasing or decreasing)
    increasing = l[1] > l[0]
    for i in range(2, len(l)):
        if increasing:
            if l[i] < l[i-1]:
                return False
        else:
            if l[i] > l[i-1]:
                return False
    return True

